static bool Prot(string n){n=n.ToLower();foreach(var s in Safe)if(n==s||n==s+".exe")return true;return false;}
static int Risk(string n,double cpu,string path,out string L){int s=0;var l=(n+" "+path).ToLower();if(l.Contains("temp")&&!l.Contains("windows"))s+=25;if(cpu>30)s+=30;if(n.Length>16)s+=10;if(n.ToLower().Contains("check")||n.ToLower().Contains("update"))s+=15;L=s>=60?"Alto rischio":s>=35?"Sospetto":s>=15?"Non firmato":"Sicuro";return s;}
void Ref(){try{var ps=Process.GetProcesses();var now=DateTime.Now;double ms=(now-lt).TotalMilliseconds;int cores=Environment.ProcessorCount;var cur=new List<Tuple<Process,double,string>>();foreach(var p in ps){double cpu=0;try{if(last.TryGetValue(p.Id,out var o)){cpu=(p.TotalProcessorTime-o).TotalMilliseconds/ms/cores*100;if(cpu<0)cpu=0;}}catch{}string path="";try{path=p.MainModule?.FileName??"";}catch{}cur.Add(Tuple.Create(p,cpu,path));try{last[p.Id]=p.TotalProcessorTime;}catch{}}lt=now;var keep=new HashSet<int>();foreach(var c in cur)keep.Add(c.Item1.Id);var dead=new List<int>();foreach(var k in last.Keys)if(!keep.Contains(k))dead.Add(k);foreach(var d in dead)last.Remove(d);
cur.Sort((a,b)=>b.Item2.CompareTo(a.Item2));lv.BeginUpdate();lv.Items.Clear();tp.Clear();int thr=0;double sum=0;int cnt=0;string f=(q?.Text??"").ToLower();int show=0;
foreach(var c in cur){if(show>=80)break;var p=c.Item1;string L;int r=Prot(p.ProcessName)?0:Risk(p.ProcessName,c.Item2,c.Item3,out L);if(Prot(p.ProcessName))L="Sistema";if(f!=""&&!p.ProcessName.ToLower().Contains(f))continue;double ram=0;try{ram=p.WorkingSet64/1048576.0;}catch{}sum+=c.Item2;cnt++;
var it=new ListViewItem(p.ProcessName);it.SubItems.Add(p.Id.ToString());it.SubItems.Add(c.Item2.ToString("F1")+"%");it.SubItems.Add(ram.ToString("F0"));it.SubItems.Add(L+" "+r);it.UseItemStyleForSubitems=false;
Color col=r>=60?Color.FromArgb(255,107,94):r>=35?Color.FromArgb(245,158,11):r>=15?Color.FromArgb(245,158,11):Color.FromArgb(16,185,129);if(Prot(p.ProcessName))col=Color.FromArgb(16,185,129);
it.SubItems[4].ForeColor=col;if(r>=35&&!Prot(p.ProcessName)){it.BackColor=Color.FromArgb(40,20,20);thr++;}
