lv.EndUpdate();int h=cnt>0?(int)Math.Max(0,100-sum/cnt*1.2):100;ring.Text=h.ToString();ring.ForeColor=h<45?Color.FromArgb(255,107,94):h<75?Color.FromArgb(245,158,11):Color.FromArgb(16,185,129);
