void Clean(){if(MessageBox.Show("One-Click Clean? Max 10, critici protetti.","Pulse",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;int k=0;foreach(var p in Process.GetProcesses()){if(k>=10)break;try{if(Prot(p.ProcessName))continue;var o=last.TryGetValue(p.Id,out var t)?t:p.TotalProcessorTime;double cpu=(p.TotalProcessorTime-o).TotalMilliseconds/2000/Environment.ProcessorCount*100;if(cpu>30){p.Kill();k++;}}catch{}}MessageBox.Show("Isolati: "+k+". Critici intatti.");Ref();}
